import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    customer_profile = inputs["customer_profile"].copy()
    profile_changes = inputs["profile_changes"].copy()

    # Ensure proper types
    customer_profile["customer_id"] = customer_profile["customer_id"].astype("int64")
    customer_profile["updated_seq"] = customer_profile["updated_seq"].astype("int64")
    profile_changes["change_seq"] = profile_changes["change_seq"].astype("int64")
    profile_changes["customer_id"] = profile_changes["customer_id"].astype("int64")

    # Convert email/phone/tier to string type (NaN for missing)
    for col in ["email", "phone", "tier"]:
        if col in customer_profile.columns:
            customer_profile[col] = customer_profile[col].astype("object")
        if col in profile_changes.columns:
            profile_changes[col] = profile_changes[col].astype("object")

    # Build result by processing each customer
    result_rows = []

    all_customer_ids = set(customer_profile["customer_id"].unique())
    if not profile_changes.empty:
        all_customer_ids.update(profile_changes["customer_id"].unique())

    for cust_id in sorted(all_customer_ids):
        # Get existing profile row if it exists
        existing = customer_profile[customer_profile["customer_id"] == cust_id]
        has_existing = len(existing) > 0

        if has_existing:
            existing_row = existing.iloc[0].copy()
            current_email = existing_row["email"]
            current_phone = existing_row["phone"]
            current_tier = existing_row["tier"]
            current_seq = existing_row["updated_seq"]
        else:
            current_email = None
            current_phone = None
            current_tier = None
            current_seq = -1

        # Get applicable changes (change_seq > updated_seq for existing, all for new)
        changes = profile_changes[profile_changes["customer_id"] == cust_id].copy()
        if has_existing:
            changes = changes[changes["change_seq"] > current_seq]

        # Sort by change_seq to apply in order
        changes = changes.sort_values("change_seq").reset_index(drop=True)

        # Apply changes
        for _, change_row in changes.iterrows():
            change_seq = change_row["change_seq"]

            # Save original values to detect no-op
            orig_email = current_email
            orig_phone = current_phone
            orig_tier = current_tier

            # Apply field rules
            # email
            if pd.notna(change_row["email"]):
                if change_row["email"] == "<<NULL>>":
                    current_email = None
                else:
                    current_email = change_row["email"].lower().strip()

            # phone
            if pd.notna(change_row["phone"]):
                if change_row["phone"] == "<<NULL>>":
                    current_phone = None
                else:
                    current_phone = change_row["phone"]

            # tier
            if pd.notna(change_row["tier"]):
                if change_row["tier"] == "<<NULL>>":
                    current_tier = None
                else:
                    current_tier = change_row["tier"]

            # Check if this is a no-op (only for existing customers)
            if has_existing:
                is_noop = (
                    _null_safe_eq(current_email, orig_email) and
                    _null_safe_eq(current_phone, orig_phone) and
                    _null_safe_eq(current_tier, orig_tier)
                )
                if not is_noop:
                    current_seq = change_seq
            else:
                # For new customers, creation is never a no-op
                current_seq = change_seq
                has_existing = True

        # Add result row
        result_rows.append({
            "customer_id": cust_id,
            "email": current_email,
            "phone": current_phone,
            "tier": current_tier,
            "updated_seq": current_seq
        })

    # Build result dataframe
    if result_rows:
        new_profile = pd.DataFrame(result_rows)
    else:
        new_profile = pd.DataFrame(columns=["customer_id", "email", "phone", "tier", "updated_seq"])

    # Set types
    new_profile["customer_id"] = new_profile["customer_id"].astype("int64")
    new_profile["updated_seq"] = new_profile["updated_seq"].astype("int64")
    for col in ["email", "phone", "tier"]:
        new_profile[col] = new_profile[col].astype("object")

    return {"new_profile": new_profile}


def _null_safe_eq(a, b):
    """Check equality with None/NaN handling (None == None is True)."""
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    if pd.isna(a) and pd.isna(b):
        return True
    if pd.isna(a) or pd.isna(b):
        return False
    return a == b
